function ensureStore($db,$name){$name=trim((string)$name);if($name===''){return false;}$chk=$db->prepare('SELECT id FROM stores WHERE name=:n');$chk->bindValue(':n',$name,SQLITE3_TEXT);$row=$chk->execute()->fetchArray(SQLITE3_ASSOC);if($row){return ['id'=>(string)$row['id'],'name'=>$name,'visible'=>true];}$maxOrd=(int)$db->query('SELECT COALESCE(MAX(sort_order),0)+1 FROM stores')->fetchArray(SQLITE3_NUM)[0];$id=(string)round(microtime(true)*1000).bin2hex(random_bytes(4));$st=$db->prepare('INSERT OR IGNORE INTO stores(id,name,visible,sort_order) VALUES(:id,:n,1,:o)');$st->bindValue(':id',$id,SQLITE3_TEXT);$st->bindValue(':n',$name,SQLITE3_TEXT);$st->bindValue(':o',$maxOrd,SQLITE3_INTEGER);$st->execute();$dates=$db->query('SELECT DISTINCT date FROM expenses');while($dateRow=$dates->fetchArray(SQLITE3_ASSOC)){$ist=$db->prepare('INSERT OR IGNORE INTO expenses(date,store,amount) VALUES(:d,:s,0)');$ist->bindValue(':d',$dateRow['date'],SQLITE3_TEXT);$ist->bindValue(':s',$name,SQLITE3_TEXT);$ist->execute();}return ['id'=>$id,'name'=>$name,'visible'=>true];}
